// 对 Wails bindings 的薄封装：组件只依赖本模块，便于测试时 mock。
// 绑定层的 Go 切片可能为 null，这里统一归一化为空数组。
import { Events } from '@wailsio/runtime';
import * as PerfService from '../bindings/unityperfagent/services/perfservice.js';
import type { AgentLogEntry, AgentModelOption, FrameData, Handshake, ImportProgressEvent, LLMConfig, ProbeResult, Report, SampleNode, Stats, Status, TickEvent } from './types';
import { normalizeSampleTree } from './lib/sample';
import { normalizeLLMConfig } from './lib/llmConfig';

// Bindings are regenerated by Wails during the build. This local type keeps
// frontend tests usable before a developer has run the generator.
type AgentLogService = {
  AgentLogs: () => Promise<AgentLogEntry[] | null>;
  ClearAgentLogs: () => Promise<void>;
  OpenAgentLog: () => Promise<void>;
};
const agentLogService = PerfService as typeof PerfService & AgentLogService;

export const api = {
  connectUSB: (serial = '', packageId = ''): Promise<Handshake> => PerfService.ConnectUSB(serial, packageId),
  disconnect: (): Promise<void> => PerfService.Disconnect(),
  status: (): Promise<Status> => PerfService.Status(),
  frames: (offset: number, limit: number): Promise<FrameData[]> =>
    PerfService.Frames(offset, limit).then((rows) => rows ?? []),
  frameAt: (index: number): Promise<FrameData> => PerfService.FrameAt(index),
  latest: (n: number): Promise<FrameData[]> => PerfService.Latest(n).then((rows) => rows ?? []),
  stats: (): Promise<Stats> => PerfService.Stats(),
  analyze: (): Promise<Report> =>
    PerfService.Analyze().then((r) => ({ ...r, issues: r.issues ?? [] }) as Report),
  clear: (): Promise<void> => PerfService.Clear(),
  setRecording: (on: boolean): Promise<void> => PerfService.SetRecording(on),
  exportCapture: (path: string): Promise<void> => PerfService.ExportCapture(path),
  importCapture: (path: string): Promise<number> => PerfService.ImportCapture(path),
  setDeepProfiling: (on: boolean): Promise<void> => PerfService.SetDeepProfiling(on),
  setCallStacks: (on: boolean): Promise<void> => PerfService.SetCallStacks(on),
  frameHierarchy: (index: number): Promise<SampleNode[]> =>
    PerfService.FrameHierarchy(index).then((rows) => normalizeSampleTree(rows)),
  diagnose: (): Promise<string> => PerfService.Diagnose(),
  llmConfig: (): Promise<LLMConfig> =>
    PerfService.LLMConfig().then((cfg) => normalizeLLMConfig({
      activeId: cfg.activeId ?? '',
      agents: (cfg.agents ?? []).map((a) => ({
        id: a.id ?? '',
        name: a.name ?? '',
        command: a.command ?? '',
        args: a.args ?? [],
        workDir: a.workDir ?? '',
        model: a.model ?? '',
        effort: a.effort ?? '',
      })),
      agentCommand: cfg.agentCommand ?? '',
      agentArgs: cfg.agentArgs ?? [],
      workDir: cfg.workDir ?? '',
    })),
  setLLMConfig: (cfg: LLMConfig): Promise<void> => PerfService.SetLLMConfig(cfg),
  listAgentModels: async (cfg: LLMConfig): Promise<AgentModelOption[]> => {
    try {
      const rows = await PerfService.ListAgentModels(cfg);
      return (rows ?? [])
        .map((m) => ({ id: m.id ?? '', label: (m.name || m.id) ?? '' }))
        .filter((m) => m.id !== '');
    } catch {
      return [];
    }
  },
  probeAgent: async (cfg: LLMConfig): Promise<ProbeResult> => {
    try {
      const r = await PerfService.ProbeAgent(cfg);
      return {
        ok: r?.ok === true,
        name: r?.name ?? '',
        message: (r?.message ?? '').trim() || (r?.ok ? 'ACP 握手成功' : '检测失败（无返回信息）'),
      };
    } catch (e) {
      return { ok: false, name: '', message: String(e) };
    }
  },
  agentChatSend: (message: string): Promise<string> => PerfService.AgentChatSend(message),
  agentChatClose: (): Promise<void> => PerfService.AgentChatClose(),
  agentLogs: (): Promise<AgentLogEntry[]> => agentLogService.AgentLogs().then((rows) => rows ?? []),
  clearAgentLogs: (): Promise<void> => agentLogService.ClearAgentLogs(),
  openAgentLog: (): Promise<void> => agentLogService.OpenAgentLog(),
  onTick: (handler: (ev: TickEvent) => void): (() => void) =>
    Events.On('perf:tick', (ev: { data: TickEvent }) => handler(ev.data)),
  onImportProgress: (handler: (ev: ImportProgressEvent) => void): (() => void) =>
    Events.On('perf:import-progress', (ev: { data: ImportProgressEvent }) => handler(ev.data)),
  onAgentChunk: (handler: (text: string) => void): (() => void) =>
    Events.On('agent:chunk', (ev: { data: { text: string } }) => handler(ev.data?.text ?? '')),
};
